287	/// Compiles a single document.
288	fn compile_document<'a>(
289	    engine: &mut Engine,
290	    document: &'a Packed<DocumentElem>,
291	    styles: StyleChain<'a>,
292	    locator: Locator<'a>,
293	) -> SourceResult<BundleDocument> {
